<?php require 'includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$pw=$_POST['password']??'';if($pw!==($_POST['confirm_password']??'')){flash('Passwords do not match.');}else{try{$q=$pdo->prepare('INSERT INTO faculty(name,email,subject,password,is_approved) VALUES(?,?,?,?,0)');$q->execute([$name,$email,$subject,password_hash($pw,PASSWORD_DEFAULT)]);flash('Faculty registration submitted for admin approval.');go('faculty_login.php');}catch(PDOException $e){flash('Registration failed. Email may already exist.');}}} page_start('Faculty Registration'); ?>
<div class="vc-card"><h2>Faculty Registration</h2><form method="post"><?php field('name','Full Name');field('email','Email','email');field('subject','Subject');field('password','Password','password');field('confirm_password','Confirm Password','password');?><button class="btn btn-success">Register</button></form></div><?php page_end(); ?>
